(7411494, 1167959, 32108, '<td valign="top">My interpretation of this challenge was not to just simply take a photo ( good or bad) and rotate it to an angle. Do you believe your image has benefited by this?</td>', 'My interpretation of this challenge was not to just simply take a photo ( good or bad) and rotate it to an angle. Do you believe your image has benefited by this?', '2015-10-21 20:00:14.000000', NULL, 1),
(7411495, 1168110, 32108, '<td valign="top">It''s just my opinion of course but I believe the flare, while trendy, has washed out too much contrast from your image. Your main subject is too small in the frame and not separated enough from the BG, and finally your leading line and main diagonal component does not add an aesthetic to the image.</td>', 'It''s just my opinion of course but I believe the flare, while trendy, has washed out too much contrast from your image. Your main subject is too small in the frame and not separated enough from the BG, and finally your leading line and main diagonal component does not add an aesthetic to the image.', '2015-10-21 20:04:48.000000', NULL, 1),
(7411496, 1168046, 32108, '<td valign="top">Good separation from BG and definitely fits the challenge but the pp is not great IMHO</td>', 'Good separation from BG and definitely fits the challenge but the pp is not great IMHO', '2015-10-21 20:06:23.000000', NULL, 1),
(7411497, 1168084, 32108, '<td valign="top">I think the concept is good but not so much on the execution, perhaps the light is too flat</td>', 'I think the concept is good but not so much on the execution, perhaps the light is too flat', '2015-10-21 20:07:31.000000', NULL, 1),
(7411498, 1168059, 32108, '<td valign="top">I dig the diagonal in the tree line but feel this image lacks a subject</td>', 'I dig the diagonal in the tree line but feel this image lacks a subject', '2015-10-21 20:08:51.000000', NULL, 1),
(7411499, 1168001, 32108, '<td valign="top">Good capture of the Rays but I feel the clouds may be over cooked</td>', 'Good capture of the Rays but I feel the clouds may be over cooked', '2015-10-21 20:10:21.000000', NULL, 1),
(7411500, 1168123, 32108, '<td valign="top">My eye is trying to focus on the brightest part of the dog which means you needed to either make the fang &amp;whisker lighter or change the point of focus to the eye.</td>', 'My eye is trying to focus on the brightest part of the dog which means you needed to either make the fang &whisker lighter or change the point of focus to the eye.', '2015-10-21 20:13:57.000000', NULL, 1),
(7411502, 1167879, 32108, '<td valign="top">My feeling is the strong horizon is overpowering the weaker diagonals in the clouds</td>', 'My feeling is the strong horizon is overpowering the weaker diagonals in the clouds', '2015-10-21 20:15:09.000000', NULL, 1),
(7411503, 1168129, 32108, '<td valign="top">Certainly in your face diagonal which I feel could have benefited from better light (earlier or later in the day) and a shallower DoF.</td>', 'Certainly in your face diagonal which I feel could have benefited from better light (earlier or later in the day) and a shallower DoF.', '2015-10-21 20:18:00.000000', NULL, 1),
